using System.Security.Cryptography;
using System.Text.Json.Nodes;
internal static class FunCycleChecks {
 static int CountWatches(JsonNode? node){if(node is JsonObject obj)return (obj["_tpl"]?.GetValue<string>()=="a7e000000000000000000113"?1:0)+obj.Where(p=>p.Key!="localAssistantFunQuarantine").Sum(p=>CountWatches(p.Value));return node is JsonArray array?array.Sum(CountWatches):0;}
 internal static void Run(string fixture,string mode){string file=Directory.GetFiles(Path.Combine(fixture,"user/profiles"),"*.json").First(),backup=Path.Combine(fixture,".assistant-safety-profile-original"),marker=Path.Combine(fixture,".assistant-safety-watch-id");
  if(mode=="--prepare-quarantine"){if(File.Exists(backup))throw new Exception("Existing quarantine test backup must be restored first");File.WriteAllBytes(backup,File.ReadAllBytes(file));string id=Convert.ToHexString(RandomNumberGenerator.GetBytes(12)).ToLowerInvariant();var root=JsonNode.Parse(File.ReadAllText(file))!;File.WriteAllText(marker,id+"\n"+CountWatches(root));var inventory=root["characters"]!["pmc"]!["Inventory"]!;inventory["items"]!.AsArray().Add(new JsonObject{["_id"]=id,["_tpl"]="a7e000000000000000000113",["parentId"]=inventory["stash"]!.GetValue<string>(),["slotId"]="hideout",["location"]=new JsonObject{["x"]=0,["y"]=0,["r"]=0}});File.WriteAllText(file,root.ToJsonString());Console.WriteLine("Prepared isolated fun-item quarantine fixture");return;}
  var state=JsonNode.Parse(File.ReadAllText(file))!.AsObject();var mark=File.ReadAllLines(marker);string watch=mark[0];bool Has(JsonNode? node){if(node is JsonObject obj){if(obj["_id"]?.GetValue<string>()==watch&&obj["_tpl"]?.GetValue<string>()=="a7e000000000000000000113")return true;return obj.Any(p=>Has(p.Value));}return node is JsonArray array&&array.Any(Has);}
  if(mode=="--verify-quarantine-off"){if(!Has(state["localAssistantFunQuarantine"])||Has(state["characters"]))throw new Exception("Fun inventory was pruned instead of quarantined");Console.WriteLine("PASS real profile load preserves disabled fun item in quarantine");return;}
  if(Has(state["localAssistantFunQuarantine"])||CountWatches(state)<Int32.Parse(mark[1])+1){File.WriteAllText(Path.Combine(fixture,".assistant-quarantine-failed.json"),state.ToJsonString());throw new Exception("Re-enabled fun item was not delivered back");}Console.WriteLine("PASS re-enabling templates restores quarantined item through native mail (native IDs may change)");
 }
}
